## Why This Is Asked
This question tests candidates' familiarity with DOM manipulation, fetch, WebSocket, and Service Workers in a practical offline-first scenario.

## Key Concepts
- **Offline-first UX**: Using IndexedDB and Service Worker for data persistence and asset caching
- **Real-time updates**: WebSocket integration with in-order delivery (sequenceId) and deduplication (noteId)
- **Efficient rendering**: Debounced renders and diff-based DOM updates to minimize reflows
- **Offline queue**: Storing writes in IndexedDB when offline, then syncing with exponential backoff on reconnect

## Code Example
```javascript
function debounceRender(render, wait = 120) {
  let timeout;
  return function(...args) {
    clearTimeout(timeout);
    timeout = setTimeout(() => render.apply(this, args), wait);
  };
}

class NotesWidget {
  constructor() {
    this.notes = new Map();
    this.pendingQueue = [];
    this.sequenceId = 0;
    this.render = debounceRender(this.render.bind(this));
  }

  async init() {
    await this.loadNotes();
    this.connectWebSocket();
    this.registerServiceWorker();
    this.setupOfflineQueue();
  }

  async loadNotes() {
    const res = await fetch('/notes');
    const notes = await res.json();
    notes.forEach(note => this.notes.set(note.id, note));
    this.render();
  }

  connectWebSocket() {
    this.ws = new WebSocket('wss://api.example.com/notes');
    this.ws.onmessage = (event) => {
      const { data } = JSON.parse(event.data);
      if (data.sequenceId >= this.sequenceId) {
        this.sequenceId = data.sequenceId;
        if (!this.notes.has(data.noteId)) {
          this.notes.set(data.noteId, data);
          this.render();
        }
      }
    };
  }

  async addNote(content) {
    const note = { id: crypto.randomUUID(), content, timestamp: Date.now() };
    if (navigator.onLine) {
      await fetch('/notes', {
        method: 'POST',
        body: JSON.stringify(note),
        headers: { 'Content-Type': 'application/json' }
      });
    } else {
      await this.queueNote(note);
    }
  }

  async queueNote(note) {
    const db = await indexedDB.open('notes-queue', 1);
    const tx = db.transaction('pending', 'readwrite');
    tx.objectStore('pending').add({ ...note, retryCount: 0 });
  }

  async syncQueue() {
    const db = await indexedDB.open('notes-queue', 1);
    const tx = db.transaction('pending', 'readwrite');
    const store = tx.objectStore('pending');
    const request = store.getAll();

    request.onsuccess = async () => {
      for (const note of request.result) {
        try {
          await fetch('/notes', {
            method: 'POST',
            body: JSON.stringify(note),
            headers: { 'Content-Type': 'application/json' }
          });
          store.delete(note.id);
        } catch (e) {
          await this.exponentialBackoff(note, note.retryCount++);
        }
      }
    };
  }

  async exponentialBackoff(note, attempt) {
    const delay = Math.min(1000 * Math.pow(2, attempt), 30000);
    setTimeout(() => this.queueNote(note), delay);
  }

  render() {
    // Diff-based DOM update logic here
  }
}
```

