```javascript
// Minimal DOM patcher
class PatchStore {
  constructor(root) {
    this.root = root;
    this.items = new Map();
  }
  patch(update) {
    const { id, ts, ...rest } = update;
    const existing = this.items.get(id);
    if (!existing || ts >= existing.ts) {
      this.items.set(id, { ts, ...rest });
    }
  }
  render() {
    // naive render: rebuilds list in order
    const list = [...this.items.values()].sort((a,b)=> a.ts - b.ts);
    this.root.innerHTML = '';
    for (const it of list) {
      const el = document.createElement('div');
      el.textContent = `${it.id}: ${it.value} @ ${new Date(it.ts).toLocaleTimeString()}`;
      this.root.appendChild(el);
    }
  }
}
```

## Why This Is Asked
Tests understanding of closures, promise deduping, in-flight concurrency control, and simple caching in a realistic data-loading scenario.

## Key Concepts
- Closure-scoped internal state (inFlight, cache, queue)
- Promise coalescing for same id
- Concurrency limit with a slot-based throttle
- Time-based cache with TTL

## Code Example
```javascript
function createUserLoader() {
  const inFlight = new Map(); // id -> Promise
  const cache = new Map(); // id -> { data, expiry }
  const queue = [];
  const MAX_CONCURRENCY = 3;
  let active = 0;

  const fetchUser = async (id) => {
    const res = await fetch(`/api/user/${id}`);
    if (!res.ok) throw new Error('Network error');
    return res.json();
  };

  const tryStart = () => {
    while (active < MAX_CONCURRENCY && queue.length) {
      const { id, resolve, reject } = queue.shift();
      active++;
      const p = fetchUser(id)
        .then((data) => {
          cache.set(id, { data, expiry: Date.now() + 5 * 60 * 1000 });
          inFlight.delete(id);
          resolve(data);
        })
        .catch((err) => reject(err))
        .finally(() => { active--; tryStart(); });
      inFlight.set(id, p);
    }
  };

  const loadUser = (id) => {
    const cached = cache.get(id);
    if (cached && cached.expiry > Date.now()) return Promise.resolve(cached.data);
    if (inFlight.has(id)) return inFlight.get(id);
    return new Promise((resolve, reject) => {
      queue.push({ id, resolve, reject });
      tryStart();
    });
  };

  return { loadUser };
}

// Usage
// const loader = createUserLoader();
// loader.loadUser('123').then(console.log);
```

## Purpose
Tests the ability to implement offline-first, real-time collaboration with a patch-based DOM updater and proper sequencing. Covers DOM operations, fetch, WebSocket handling, Service Worker caching, and error handling with reconnection strategies.

## Key Concepts
- Patch-based DOM updates using small, immutable operations
- Per-cell sequencing and out-of-order patch buffering
- Offline-first architecture with Service Worker stale-while-revalidate
- Reconnection strategy with exponential backoff and jitter

## Code Example
```javascript
// REST/WS wrapper with reconnection
class GridClient {
  constructor(url) { this.url = url; this.ws = null; this.seq = {}; }
  async init() {
    const layout = await fetch(this.url + '/grid').then(r => r.json());
    this.render(layout);
    this.connect();
  }
  connect() {
    this.ws = new WebSocket(this.url.replace('http','ws') + '/stream');
    this.ws.onmessage = e => this.process(JSON.parse(e.data));
    this.ws.onclose = () => setTimeout(() => this.connect(), this.backoff());
  }
  backoff() { return Math.min(30000, (this.attempts || 1) * 1000 * (0.5 + Math.random())); }

  // Patch processor with buffering
  process(patch) {
    const { cellId, seq } = patch;
    if (!this.seq[cellId] || seq > this.seq[cellId]) this.pending[cellId]?.push(patch);
    while (this.pending[cellId]?.length) {
      const p = this.pending[cellId].sort((a,b) => a.seq - b.seq).shift();
      if (p.seq === this.seq[cellId] + 1) { this.apply(p); this.seq[cellId] = p.seq; }
    }
  }
  apply({cellId, op, value}) {
    const el = document.getElementById(cellId);
    if (op === 'set') el.textContent = value;
    else if (op === 'add') el.insertAdjacentHTML('beforeend', value);
    else if (op === 'del') el.remove();
  }
}
```
